import { motion } from 'framer-motion'
import { Trash2 } from 'lucide-react'
import { cn } from '@/lib/utils'
import { formatRelativeTime } from './InkStamp'

interface EntryCardProps {
  entry: Entry
  index: number
  onDelete: (id: string) => void
}

const rotations = [-1, 0.7, -0.5, 0.9, -0.8, 0.6, -0.4, 0.8, -0.6, 0.5]

export default function EntryCard({ entry, index, onDelete }: EntryCardProps) {
  const rotation = rotations[index % rotations.length]

  return (
    <motion.article
      initial={{ opacity: 0, y: 24, rotate: rotation }}
      animate={{ opacity: 1, y: 0, rotate: rotation }}
      transition={{
        duration: 0.5,
        ease: [0.22, 1, 0.36, 1],
        delay: index * 0.06,
      }}
      whileHover={{ y: -2, rotate: 0, transition: { duration: 0.3 } }}
      className={cn(
        'group relative bg-surface rounded-lg p-6 shadow-sm',
        'border border-[#E8D5C4] hover:shadow-md',
        'transition-shadow duration-300',
      )}
      style={{
        boxShadow:
          '0 1px 3px rgba(26,20,16,0.06), 0 4px 8px rgba(26,20,16,0.04)',
      }}
    >
      {/* dot-grid overlay revealed on hover */}
      <div className="pointer-events-none absolute inset-0 rounded-lg opacity-0 group-hover:opacity-100 transition-opacity duration-500">
        <div
          className="absolute inset-0 rounded-lg"
          style={{
            backgroundImage:
              'radial-gradient(circle, rgba(139,111,94,0.12) 1px, transparent 1px)',
            backgroundSize: '16px 16px',
          }}
        />
      </div>

      {/* delete button */}
      <button
        onClick={() => onDelete(entry.id)}
        className={cn(
          'absolute top-4 right-4 p-1.5 rounded-full',
          'opacity-0 group-hover:opacity-100 transition-opacity duration-200',
          'hover:bg-[#F5EDE4] text-muted-foreground hover:text-red-500',
          'focus:outline-none focus-visible:ring-2 focus-visible:ring-primary',
        )}
        aria-label="Delete entry"

